namespace RMPCS.Core;

public sealed record HelpArticle(string Title, string Body);
public static class HelpCatalog
{
    public static IReadOnlyList<HelpArticle> Articles { get; } = new HelpArticle[]
    {
        new("Start here: v0.13.8 feature guide", "New to the recent features? Read these Help articles in order: Install optional temperature sensors; Choose and display temperature sources; Sensor setup troubleshooting; Arrange transparent metric widgets; Overlay troubleshooting; Find tools in the category tree; Drive optimization walkthrough. Use the Help search box for driver, temperature, widgets, transparent, circles, ReTRIM, sidebar, startup or updates.\n\nInstalling optional components does not enable sensors, startup, scheduling or cleanup. Each has its own setting and Apply/Save action. The app stays usable if you skip the driver. v0.14.0's first-run guide remains a manual informational preview under Settings, not an automatic setup wizard."),
        new("Install optional temperature sensors", "During EXE setup: 1. On Your preferences, optionally select Review / install optional temperature sensor package (off by default). 2. Finish the normal RMPCS installation. If Windows requires a restart, restart first and use the in-app route below. 3. Allow the separate Windows administrator prompt. 4. Read the sensor review window, then choose Download & open official setup if you agree. No download starts just by opening the review. 5. Follow the visible PawnIO vendor setup and keep its administrator-only access defaults. 6. Close the review window to return to the RMPCS installer. Cancelling this optional stage leaves RMPCS installed.\n\nStandalone MSI: after successful installation, select the optional sensor checkbox on the Finished page and choose Finish. Close skips the optional action. If Run RMPCS is also checked, the app opens after the sensor review closes; a reported restart suppresses opening. Silent/basic MSI installation never installs sensor components.\n\nInstall later or from portable: Settings > Realtime system overlay > Temperature sources > Review / install optional sensor components. A standard Windows session requests administrator permission for this setup only; cancelling UAC makes no sensor change. The same review/verification path is used by installer and app. Windows 11 x64 and internet access are required.\n\nThe setup checks pinned official package hashes, protected storage and Windows signature trust/revocation plus the expected publisher. It never disables Secure Boot, Memory Integrity or the vulnerable-driver blocklist. Signed kernel code can still have defects or firmware/anti-cheat conflicts. No fan/voltage controls are used. Restart whenever the vendor asks, even if RMPCS cannot detect that request. Installation alone leaves monitoring off. See Choose and display temperature sources next."),
        new("Choose and display temperature sources", "1. If using the optional driver, restart when requested and open RMPCS as administrator. 2. Open Settings > Realtime system overlay > Temperature sources. 3. Enable Display selected temperature sensors. For installed in-app components, also enable Allow optional in-app low-level hardware reads and choose In-app hardware as provider. 4. Choose Discover sensors from selected provider. Discovery never installs a driver. 5. Filter a category and select sensors; select up to eight across providers/categories. Switching a filter preserves selections. 6. Under Metric display styles choose Temperature sensors and enable your preferred numbers/circle/value-circle/bar/graph combination. 7. Apply overlay settings, then Show / hide overlay.\n\nWindows firmware reports firmware thermal zones, not CPU-core values. Windows storage reports only drives that expose supported counters. LibreHardwareMonitor WMI and OpenHardwareMonitor WMI require that trusted program's local WMI provider to already be running; RMPCS does not start or download it. In-app hardware uses the optional reviewed libraries and PawnIO; it does not require the external monitoring GUI. There is no automatic provider fallback.\n\nTemperature gauge reference 0-120 Celsius is a display scale, not a safety threshold. Different sensors measure different locations and may disagree. Missing, zero-sentinel, blocked or stale readings show unavailable. Queries run locally at most every five seconds, share one worker and expire cached samples after fifteen seconds. Provider-internal freshness and accuracy cannot be guaranteed. No readings are saved or uploaded."),
        new("Sensor setup troubleshooting", "UAC cancelled / no administrator rights: retry the in-app setup button when ready and approve Windows' normal prompt. Using another administrator identity can make that session's per-user preferences differ.\n\nDownload, checksum, publisher, trust or revocation error: close the sensor window, verify your connection and Windows date/time, then retry. A changed upstream package intentionally fails the pinned hash. Use an updated official RMPCS release if a pin changes; do not run a substituted download or bypass certificate validation. No unsigned/offline fallback is provided. Trust verification may require certificate/revocation services to be reachable.\n\nAnother setup is busy: finish/close the other RMPCS sensor setup and retry. Do not delete lock files or forcibly terminate driver installation. A blocked query or setup can take time to return.\n\nWindows security or anti-cheat blocks the driver: leave Secure Boot, Memory Integrity and the driver blocklist enabled. Use Windows firmware/storage or an already available trusted WMI source instead. Close overlays/disable in-app reads if a game's policy requires it; even desktop overlays may be restricted.\n\nSetup closed but no temperatures: restart when requested, run RMPCS as administrator, enable both temperature monitoring and in-app reads, choose In-app hardware, discover again, select sensors and Apply. Confirm at least one display style is on. A registered PawnIO package is not proof that the driver works or supports every sensor. If a provider is still busy or unavailable, stop polling, wait and retry; restarting RMPCS clears its reader state. Firmware zones can be absent, and unsupported hardware stays unavailable.\n\nRMPCS installed but optional setup failed/cancelled: keep using RMPCS and retry its Settings button later. Uninstall RMPCS does not remove shared PawnIO or protected library files. Stop in-app monitoring and check other applications' dependencies before removing PawnIO separately in Windows Installed apps. Never delete a loaded driver or weaken component-folder permissions. Review SENSOR-SECURITY.md and THIRD-PARTY-NOTICES.md for package sources, checks and limits."),
        new("Arrange transparent metric widgets", "1. Open Settings > Realtime system overlay and select the metrics you want. 2. Optionally enable Show metrics as separate widgets. 3. Show the overlay, unlock it and leave click-through off while arranging. Each metric gets its own window; download/upload are separate and selected temperatures each get a widget. 4. Drag windows to the desired monitor/position and use their Lock controls. 5. Select Remember positions & locks, then Apply overlay settings. Individual monitor/position/lock choices persist; the main monitor choice is the default for new widgets.\n\nFully transparent background removes the window surface, not the text and gauges. Locking a transparent widget also hides its header. Windows High Contrast overrides transparency to keep surfaces readable. Turn click-through on only after positioning. Recovery: use Settings > Unlock widgets / disable click-through, arrange again, Remember positions & locks and Apply. For the combined overlay use its global lock/click-through choices and remember its position.\n\nShow/hide in Settings, the tray menu or optional Ctrl+Alt+O controls the entire session. A widget's Hide button hides only that widget; hide/show the session to restore selected widgets. Hiding every widget stops the shared sampler. RMPCS must remain running, including in the tray, for widgets to remain visible."),
        new("Overlay troubleshooting", "Nothing visible: open Settings, select at least one metric and at least one view for it, then Show / hide overlay. Show overlay when RMPCS opens controls display while RMPCS runs; it does not enable Windows sign-in startup. Use Schedules separately for installed startup-to-tray. Hidden widgets stop polling; exiting RMPCS closes them.\n\nCannot click or drag: turn click-through off; unlock the overlay or use Unlock widgets / disable click-through for separate widgets. Remember positions & locks then Apply. A locked transparent window hides its controls intentionally.\n\nOff-screen or disconnected monitor: refresh displays, choose an available monitor/corner and show the combined overlay; unlock/drag widgets and remember their positions. Missing displays fall back to an available work area. With long view combinations, disable click-through to scroll.\n\nShortcut does not work: another application may own Ctrl+Alt+O. Use Settings or the tray instead. A game in exclusive full-screen mode, Windows secure desktop or another topmost window may cover the overlay; try the game's supported borderless mode, observing its rules. No injection or anti-cheat bypass is used.\n\nDashes, spikes or unexpected rates: CPU/network need an initial sample. Counter resets, adapter changes, sleep and stale reads clear the baseline. VPN/virtual adapters can overlap totals. Network bars/circles use a chosen MiB/s reference, not link capacity; uptime gauges show a repeating 24-hour cycle. CPU/RAM percentages and drive available-space gauges have different meanings. A 5-second update interval and fewer graphs/widgets reduce work. Temperature sources have their own five-second polling limit. Values are not health guarantees or benchmark results."),
        new("Find tools in the category tree", "Expand or collapse a main-screen category with its plus/minus control, then select a named tool. System contains Overview; Care & optimization contains Maintenance and Drive optimization; Startup & automation contains Startup apps and Schedules; Diagnostics & recovery contains Diagnostics, Recovery and History; Personalization & support contains Settings and Help. Selecting a category runs no action.\n\nBack, Alt+Left or the mouse Back button returns through visited sections; Quit RMPCS closes the app separately. Sidebar mode uses the compact page picker with the same tools plus Results & activity. Full window restores the categorized layout without discarding the session."),
        new("Drive optimization walkthrough and troubleshooting", "1. Select Care & optimization > Drive optimization (or Drive optimization in the sidebar picker). 2. Refresh and select a supported volume. 3. For an HDD, run Analyze drive, review Windows' output, then choose Defragment HDD only if needed. Analysis must be successful within fifteen minutes and at least 15% space must be free. 4. For a verified SSD, use ReTRIM SSD, Windows' equivalent of fstrim. SSDs never receive a traditional defragmentation request. 5. Review Results & activity and History for completion.\n\nUse an administrator session and AC power. Unknown/contradictory media, unsupported topology/filesystem, RAID/USB/virtual/dynamic/recovery storage, dirty/read-only volumes and inaccessible drives are blocked rather than guessed. Refresh after connecting or changing storage. Windows' own drive optimization schedule stays unchanged; this manual tool is excluded from one-click/scheduled care. Keep the PC powered on and allow a running optimizer to finish; RMPCS does not forcibly kill disk work. A success code does not prove a speed improvement or drive health. Keep backups and investigate hardware errors separately."),
        new("Temperatures and optional kernel sensor driver", "Settings > Realtime system overlay > Temperature sources lets you discover one selected local provider and choose up to eight sources across categories/providers. Windows firmware zones are not CPU-core temperatures. Windows storage and already running LibreHardwareMonitor/OpenHardwareMonitor WMI providers need no new RMPCS driver installation. Optional in-app CPU/GPU/motherboard reads require an administrator session and reviewed components. Review / install optional sensor components downloads pinned official LibreHardwareMonitor 0.9.6 libraries and PawnIO 2.2.0 setup, checks hashes, protected paths and the setup's Windows trust/revocation and pinned publisher signature, then opens visible vendor setup. Keep administrator-only access defaults. Nothing installs silently or enables low-level reads automatically. Secure Boot, Memory Integrity and the driver blocklist are never weakened; blocked hardware remains unavailable. Signed kernel code may still contain defects or conflict with anti-cheat/firmware. Remove the shared PawnIO package separately through Windows Installed apps after checking other programs do not need it. No fan/voltage controls are exposed. Temperature values and providers can be inaccurate; the 0-120 Celsius display reference is not a safety limit. Sources are serialized, queried at most every five seconds, and cached samples expire after fifteen seconds; no readings are saved or uploaded."),
        new("Transparent overlay and individual widgets", "Enable Fully transparent background to remove the overlay surface while retaining metric text and graphics. Locking also hides its header. High Contrast retains solid readable surfaces. Show metrics as separate widgets creates independent draggable and lockable windows with a shared sampler. Remember positions & locks then Apply overlay settings saves each monitor, position and lock. Unlock widgets / disable click-through in Settings recovers locked transparent windows. Hide/show in Settings, tray or the optional shortcut controls the entire session. Hiding every widget stops polling. Turning off a metric removes its widget. The main window can reside in the tray while widgets remain visible. These are desktop windows without game injection; exclusive full-screen and other topmost apps may cover them."),
        new("Overlay circles, values, bars and graphs", "Settings > Realtime system overlay > Metric display styles edits each metric's presentation independently of its on/off switch. Combine any of five checkboxes: standalone numbers, plain circle, circle with numerical value inside, bar, graph. Numbers + a value circle can appear together; plain and value circles can also coexist. Switch the editor metric to preserve different choices for CPU, RAM, Network, drive space and uptime, then Apply overlay settings. Download/upload use separate displays with the same network view options. CPU/RAM represent usage; drive gauges represent available-space percentage. Network gauges/graphs use the selected MiB/s reference rather than link capacity, with above-reference labeling; value circles retain actual rates. Uptime visuals represent the current 24-hour uptime cycle and value circles show the actual elapsed duration. Unknown data produces an unfilled, unavailable gauge, never an invented zero. All views off hides that metric and stops its collection without changing its selected on/off state; all metrics/views off pauses sampling. Long combinations can scroll when click-through is off. Display styles themselves add no sensors, animations or sampling workers. Optional temperature providers and components are configured separately. Older v0.13.5 numeric/graph preferences migrate automatically."),
        new("Realtime system monitoring overlay", "Settings > Realtime system overlay controls an optional local CPU/RAM/network/system-drive-free-space/uptime overlay. Off by default; Show / hide previews choices, Apply overlay settings saves them, and Show overlay when RMPCS opens enables automatic display only while the desktop app runs. This does not enable Windows sign-in startup. Choose 1/2/5-second updates, metrics, graphs, font, text size, opacity, width, monitor, corner, topmost, position lock and click-through. Drag when unlocked, then Remember positions & locks and Apply to remember it. The tray or optional Ctrl+Alt+O shortcut toggles visibility; Settings always allows recovery from click-through. Shortcut conflicts are reported. Hiding stops sampling and clears the in-memory history; exiting closes the overlay. Sampling never overlaps and CPU/RAM graphs retain at most 60 samples. System-drive available space refreshes at most every 30 seconds. CPU/rates need a baseline; counter resets, adapter-set changes and long sampling gaps show unavailable rather than false zeros/spikes. Network aggregates active non-loopback/non-tunnel adapters; VPN/virtual adapters may double-count traffic. CPU readings on systems with more than 64 logical processors are unavailable. Uptime follows Windows' uptime counter and Fast Startup may preserve it. Basic counters need no driver, internet access or administrator rights. Temperatures use separately enabled providers, with an optional reviewed component setup for low-level sensors. No FPS/disk-activity sensors, process injection or saved monitoring history. Exclusive full-screen and other topmost apps may cover it. High Contrast forces solid, fully opaque surfaces. Multi-monitor/DPI and hotkey behavior still need supervised desktop validation."),
        new("First-run setup guide preview", "v0.13.5 contains the reusable step catalogue and bounded Back/Next navigation for the planned v0.14.0 setup guide. Settings > Getting started guide opens an informational preview. It never applies settings, enables startup, elevates privileges, contacts services or runs maintenance. Close it at any time. Automatic first-run detection, saved completion state and review/apply of choices are reserved for v0.14.0."),
        new("Drive analysis, HDD defragmentation and SSD ReTRIM", "Drives is an on-demand tool, excluded from one-click and scheduled maintenance. Refresh reads native Windows storage descriptors. Only accessible local NTFS volumes on one basic ATA/SATA/NVMe data partition are supported. Unknown or contradictory media, RAID, USB, virtual, dynamic, recovery, dirty and read-only storage is blocked. SSDs receive only ReTRIM, Windows' equivalent of fstrim; traditional defragmentation is never requested on SSDs. HDDs require successful analysis within 15 minutes and 15% free space. Review Windows' analysis report before choosing defragmentation. Administrator rights are required; optimization also needs AC power. Drive identity and safety checks repeat immediately before launch. Windows defrag.exe runs at its default low priority on one stable volume GUID, without a shell. Wait for completion; RMPCS does not forcibly kill disk work. Windows' own optimization schedule is unchanged, and repeated manual runs are usually unnecessary. Output and exit status are saved in History. A success code does not prove a performance gain. Native checks cannot establish hardware reliability or compensate for a controller that reports incorrect information. Keep backups; this tool does not repair a failing drive."),
        new("Fonts, navigation and interface preferences", "Settings > Fonts & appearance offers Barlow, Rajdhani, Atkinson Hyperlegible, Lato, Poppins, Hind, PT Sans and Oxygen as bundled interface fonts, plus Windows system. Theme palette includes 14 presets; Ocean Slate, Nordic Frost, Forest Mist, Warm Sand, Rose Quartz and Graphite coordinate Light/Dark backgrounds, cards, text and controls. System mode follows Windows, and High Contrast overrides custom colors. Font and color choices preview immediately; Save appearance keeps them, and Discard preview restores the saved choices. No font is installed in Windows or fetched from a server. Unrecognized font preference values normalize to Barlow rather than loading a file or URL. Bundled font copyright/license texts are included in the application directory as OFL-barlow.txt, OFL-rajdhani.txt and OFL-atkinsonhyperlegible.txt and the matching OFL-lato/poppins/hind/ptsans/oxygen.txt files, with THIRD-PARTY-NOTICES.md. Settings is grouped into appearance, sidebar/displays, window/defaults, GitHub updates and installation/automation. Save preferences applies the general settings. The Updates header shortcut expands the correct group. Back returns through recently visited sections, including sidebar Results & activity. Alt+Left and the mouse Back button do the same. Back never undoes task selections, cancels maintenance, runs a task or exits. Quit RMPCS is the separate app-closing action; it waits for active work. Closing/minimizing still follows your tray preferences. Keyboard focus, text selection/copy and report scrolling remain available with the themed controls."),
        new("Sidebar mode and reserved desktop space", "Choose Sidebar in the main header for a compact single-pane layout. The page picker includes every existing page plus Results & activity; checks, cleanup previews and maintenance show their output there. All task selections, administrator requirements and confirmations are unchanged. Full window restores the normal layout without discarding the current session. In Settings > Sidebar choose Left or Right, the current monitor or a specific DISPLAY identifier, and a width of 360, 400, 440 or 480 scaled units. Apply sidebar settings saves only these choices; Save preferences also includes them. Current monitor is captured when sidebar mode opens and retained while it is active. A disconnected display falls back to an available monitor with a visible status. Refresh displays updates the selection list. Reserve desktop space is optional and uses the Windows appbar service so maximized ordinary windows leave room. It never writes the global work-area setting. Space is released on hide, minimize, full-window mode or exit, and reacquired when shown. Start-in-tray does not reserve space while hidden. Sidebar stays above ordinary windows but full-screen apps, other topmost windows and Windows security UI can overlap it. If the shell cannot reserve space, the app reports overlay fallback. Width is capped at half the monitor; very small/high-scale displays can require scrolling. Preferences are per Windows identity and support interface undo. No maintenance is started by changing layouts."),
        new("Crash and stability diagnostics", "Diagnostics summarizes recent System/Application events for 1, 7 or 30 days, with up to 100 matching events per channel. Only timestamps, channel/provider, ID and level are read; event messages and machine/user identifiers are excluded. Recurring-ID counts describe this sample, not all crashes or a proven cause. Missing events do not prove stability. Read and explicitly export the displayed report if you want to keep it. Reports are never uploaded."),
        new("Network diagnostics and comparisons", "Diagnostics tests DNS and HTTPS HEAD against a fixed Microsoft or GitHub host, then five ICMP probes to one OS-configured gateway. It never flushes DNS or releases DHCP. Requests have deadlines, do not follow redirects, use normal TLS validation and send no account credentials. ICMP may be blocked, and gateway latency is not Internet latency. Multiple adapters/VPNs can make the first available gateway unrepresentative. Use result as baseline, perform any chosen manual repair separately, and run again to compare the same target/gateway. Baselines live only in memory; export explicitly to retain them. Private gateway addresses may be present. Natural variation cannot prove a repair helped. Export requires a new local file without links; a failed export may leave an empty/partial file."),
        new("Restore points before Windows repairs", "Recovery can request and verify a new Windows restore point with administrator rights. Optionally enable Request a restore point before manual Windows repairs in Settings and Save. This applies to DISM, SFC and Search reset, never cleanup-only or unattended runs. The app compares a fresh matching description/sequence against the prior inventory; an accepted request without a new point is reported as unverified. Frequency limits or disabled/unavailable protection can prevent creation. RMPCS never changes System Protection, service configuration or creation frequency. If pre-repair verification fails, continuing without it requires a separate default-No confirmation. An active request is allowed to finish. System Restore does not recover permanently deleted personal files, and RMPCS never restores the OS automatically."),
        new("Undo RMPCS preferences", "Recovery can undo the most recent saved interface/tray/update/repair preference change for the running Windows identity. A one-step local record retains the previous and expected current normalized values. Undo refuses a conflicting later state; Save/Reset replaces the record. Administrator-prompt undo is separate, requires the elevated protected installed copy, and can only be used by the same Windows identity that made the machine-wide change. Undo affects only RMPCS preferences, not cleanup, repairs, schedules or third-party settings. Startup entries can be restored with their separate startup switch. These records are not a tamper-proof audit history."),
        new("Workload deferral and maintenance start windows", "Schedules offers optional 1/2/4-hour start windows after the scheduled local time and 15/30/60-minute maximum workload waits. Defaults are off, preserving existing schedules until you explicitly save a change. CPU at least 70%, RAM at least 85%, aggregate adapter traffic at least 5 MiB/s, full-screen/presentation/quiet signals, active microphone sessions or unavailable signals defer starting. Microphone state queries do not record audio. These are best-effort signals, not identification of every game/call/download. Idle/AC requirements are rechecked during waiting. Deferrals recheck at most once a minute and skip when the wait/window expires; timed-out workload preflights skip. A weekly window crossing midnight belongs to its scheduled start day. Local wall-clock changes/DST can change window eligibility. The window governs starting only: active repairs are never killed by these guards. History records skips; opt-in completion notices can report them when a tray instance is available."),
        new("Run summaries and space measurements", "Manual and scheduled runs save a before/after summary in the session log. The last manual summary also appears below Activity. Confirmed deletion totals report logical file size, not physically reclaimed space. Recycle Bin reductions are estimates. The read-only free-space observation covers the Windows OS drive; other programs, compression, allocation and Windows servicing can change it, including a negative change. Failed cleanup may have incomplete counters. Read repair output before concluding that anything was fixed."),
        new("Create diagnostic log archives", "In History, archive the selected saved run or the latest 30 saved run logs. The ZIP keeps originals and contains only RMPCS logs plus a review manifest; it does not gather event channels, browser files or crash dumps. Limits are 30 logs, 8 MiB each and 32 MiB total source data. Active, inaccessible, linked and oversized files are skipped. Choose a new filename in a normal local folder: existing files are not overwritten. Logs can contain private paths and command output. ZIP archives are not encrypted and are never uploaded by RMPCS. Review/redact their contents yourself before sharing. Archive failure may leave an incomplete ZIP; original logs remain unchanged."),
        new("Maintenance completion notifications", "Enable completion/failure notices in Settings and Save preferences. They are off by default and require the app's tray icon to be resident in the same Windows sign-in session. Manual runs notify directly; scheduled processes send only one fixed status code, with no log contents, paths or commands. Notices are informational and are not authenticated evidence of a result; verify History/Activity. Windows quiet hours or notification settings, integrity isolation, an unavailable tray or exiting the app can prevent delivery. Notices are rate-limited and are not queued for later delivery. No new scheduled task, Windows service, polling or network notification service is installed."),
        new("Themes, accents and switches", "Settings offers System (follow Windows), Light and Dark modes with eight LootDrop-inspired accent presets and a custom six-digit HEX or RGB color. Appearance previews across app views, inputs, switches, result text, confirmations and tray menus. Use Save appearance to persist only the look, Save preferences to save all general settings, or Discard preview to return to the saved look. Windows High Contrast takes priority. Text and accent labels choose contrasting colors; keyboard focus remains visible. Custom colors are data, not external theme files, URLs or executable code. Windows-owned file pickers, UAC and installer surfaces keep their OS/installer styling. Other preference switches require Save preferences; administrator prompting has its own Apply button. Startup and schedule switches apply only after their explicit confirmation. Maintenance task selections remain checkboxes and do not run until you choose Run selected tasks and confirm."),
        new("Getting started", "Rusty's PC Toolkit (RMPCS) brings Windows maintenance into one place. Start with Overview and Check my PC for a read-only snapshot. In Maintenance, select tasks, preview file cleanup, then review the confirmation before running. No maintenance starts just because you open the app. Recommended care includes seven-day temporary-file cleanup, DNS flushing, DISM and SFC. Save your work before choosing any restart."),
        new("Administrator access", "Health checks, preferences, Help and update checking can be used in a standard session. Maintenance, startup-entry changes and automatic tasks require administrator rights. Use Run as administrator. The installed edition can remember an always-request-administrator preference in Settings. Windows UAC still asks for approval when necessary. Cancelling UAC leaves a standard session with protected actions disabled. Different administrator credentials apply settings/history to that Windows identity."),
        new("Cleanup previews and age", "Preview selected file cleanup shows eligible counts, estimated size and skipped entries without deleting. Running rescans, so results can change. Both creation and modification times must meet the selected cutoff. Locked/protected files, links and hard-linked files are skipped. Files are permanently deleted, bypassing the Recycle Bin. Settings can choose a default one-, seven- or thirty-day cutoff; it affects manual selection only. Scheduled profiles keep their fixed seven-day policy."),
        new("Additional and advanced cleanup", "Thumbnail caches are recreated by Windows. Archived error reports and crash dumps may be needed to investigate crashes. Recycle Bin emptying permanently removes all current items regardless of age. Prefetch cleanup may slow launches; Windows Logs removal loses diagnostic history. Search-index reset requests a background rebuild and results may be incomplete meanwhile. These are optional choices, excluded from routine scheduled profiles. Expand the groups to review them; Select full batch opens the advanced group."),
        new("Windows repair and network tasks", "DISM runs before SFC and may contact Windows Update. If selected DISM fails, SFC is skipped. Read the command output: an exit code alone does not prove all issues were fixed. DNS flushing differs from DHCP release/renew. DHCP release interrupts internet, VPN and remote sessions; renewal is still attempted after release even on failure or Stop. Reconnection is not guaranteed. Avoid lease resets during remote support or important downloads."),
        new("Stop, restart and activity", "Stop after current task lets the current operation finish and prevents later tasks from starting. Exit cannot interrupt an active operation. A requested restart is suppressed on failures or queue stop. Cancel restart can also cancel shutdowns requested by another application. Manual/scheduled activity is saved in History; logs can contain local paths and command output. Export only what you want to share. Clearing the activity view does not delete saved logs."),
        new("Tray and sign-in startup", "Close and minimize can hide RMPCS in the system tray; change these behaviors in Settings. Click the tray icon to reopen or right-click for Open/Exit. Windows may put it in the overflow menu. Exit waits for active operations to finish. If the tray cannot be created, the window stays usable and closing exits normally. Enable startup to tray in Schedules after installing the protected copy. Portable sessions can use the tray but cannot register privileged automatic startup. Tray residency alone runs no maintenance."),
        new("Automatic maintenance schedules", "Schedules manages sign-in startup separately from maintenance schedules. Light care uses seven-day temporary-file cleanup and DNS; repair adds DISM and SFC. You must be signed in. Choose daily/weekly local PC time, idle and AC-power conditions. Theme-aware switches control RMPCS sign-in startup and scheduled maintenance; turning scheduled maintenance off removes its saved task after confirmation. Save & enable schedule applies the reviewed form. Missed runs can start later; the app does not wake the PC or terminate active repairs when activity/power changes. Advanced cleanup, DHCP resets and restarts are excluded. Disable startup/remove schedules separately; resetting interface preferences does not remove tasks."),
        new("Startup app manager and restore", "Startup inventories common Run registry entries for the current Windows identity and machine. It does not include startup folders, Windows approval state, services, scheduled tasks or packaged startup tasks. Startup switches show whether a Run entry is present. Switch off to disable with an Administrators/SYSTEM-only backup; switch on to restore that backup. Every change requires confirmation, and cancellation/failure preserves or refreshes the shown state. Restore refuses conflicting live values and never launches the stored command. Current-user changes apply to the identity running RMPCS. Disabled-entry backups remain on uninstall: restore entries first if you want those choices reversed."),
        new("GitHub updates and preview releases", "Settings offers Check for updates and an optional check on app launch, at most once per 24 hours for that Windows identity. Automatic checks are off by default and never run in scheduled maintenance processes. Include preview releases is on by default because current RMPCS builds are development prereleases. The checker reads the newest 100 releases from the official repository, compares version tags and shows plain-text notes. It never downloads or runs installers. Review the official release, exit RMPCS, then install the update yourself. Network/rate-limit errors are not reported as up to date."),
        new("Installation, portability and settings", "Use the downloaded version\u0027s RMPCS-Setup-<version>-x64.exe for prerequisite setup and the installed edition (v0.13.8 and earlier: RMPCS.Setup.exe). Choose desktop/Start Menu entries and administrator prompting before installation. On successful completion, Run RMPCS after installation opens only the app. Portable users should extract all files and open Launch-RMPCS.exe. Both editions share per-Windows-identity interface preferences and logs. General preferences are saved explicitly; the installed administrator preference has its own Apply button. Reset interface defaults does not change installer choices, startup entries, automatic tasks or saved logs."),
        new("Privacy, troubleshooting and support", "Update checks contact api.github.com with the application/version identifier and normal connection information. They send no health reports, startup commands, usernames or logs. No GitHub tokens or storefront credentials are collected. The Copy support summary button copies only app/runtime/Windows versions, architecture, administrator state and installed/portable mode; review it before sharing. If a scan fails, read Activity and unavailable-check notes. Saved logs may include private paths: review/redact them yourself before attaching them to an issue. The app is unsigned and development releases need supervised Windows testing; maintenance cannot guarantee higher FPS or repair hardware faults."),
        new("LootDrop and other projects", ProductInfo.LootDropDescription + "\n\nVisit LootDrop on GitHub using the Help button. It is a separate Degenerates Inc. application; opening its page does not install it, connect accounts or share RMPCS diagnostics.")
    };
    public static IReadOnlyList<HelpArticle> Search(string? query)
    {
        var words = (query ?? "").Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Take(12).ToArray();
        return Articles.Where(article => words.All(word => (article.Title + " " + article.Body).Contains(word, StringComparison.OrdinalIgnoreCase))).ToArray();
    }
}
